self.onmessage=async({data:m})=>{try{const {outputScale,pcmWav}=await import('./formats.mjs'),{scale,peak}=outputScale(m.channels,m.normalize,m.target);let blob;if(m.format==='wav'){blob=new Blob([pcmWav(m.channels,m.rate,m.bits,scale)],{type:'audio/wav'});}else{importScripts('./vendor/lame.min.js');const encoder=new lamejs.Mp3Encoder(m.channels.length,m.rate,m.bitrate),parts=[],n=m.channels[0].length;for(let i=0;i<n;i+=1152){const block=m.channels.map(ch=>{const out=new Int16Array(Math.min(1152,n-i));for(let j=0;j<out.length;j++){const v=Math.max(-1,Math.min(1,ch[i+j]*scale));out[j]=v*(v<0?32768:32767);}return out;});const packet=encoder.encodeBuffer(...block);if(packet.length)parts.push(new Int8Array(packet));if(i%(1152*100)===0)self.postMessage({progress:i/n});}const tail=encoder.flush();if(tail.length)parts.push(new Int8Array(tail));blob=new Blob(parts,{type:'audio/mpeg'});}self.postMessage({blob,attenuated:peak>1});}catch(e){self.postMessage({error:e.message});}};
